insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('event-images','event-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy event_images_storage_read on storage.objects for select to anon,authenticated using(bucket_id='event-images' and exists(select 1 from public.events e where e.id::text=(storage.foldername(name))[1] and (e.status='published' or private.event_role(e.id))));
create policy event_images_storage_insert on storage.objects for insert to authenticated with check(bucket_id='event-images' and exists(select 1 from public.events e where e.id::text=(storage.foldername(name))[1] and private.event_role(e.id,array['owner','admin','manager'])));
create policy event_images_storage_update on storage.objects for update to authenticated using(bucket_id='event-images' and exists(select 1 from public.events e where e.id::text=(storage.foldername(name))[1] and private.event_role(e.id,array['owner','admin','manager']))) with check(bucket_id='event-images' and exists(select 1 from public.events e where e.id::text=(storage.foldername(name))[1] and private.event_role(e.id,array['owner','admin','manager'])));
create policy event_images_storage_delete on storage.objects for delete to authenticated using(bucket_id='event-images' and exists(select 1 from public.events e where e.id::text=(storage.foldername(name))[1] and private.event_role(e.id,array['owner','admin','manager'])));
